"""Rebuild the standalone sharing document. Requires markdown2; no network at render time."""
from pathlib import Path
import base64
import re
import markdown2

root = Path(__file__).resolve().parents[2]
out = Path(__file__).resolve().parent
source = (out/'PERSONAL_TRAINING_APP_BLUEPRINT.md').read_text()
body = markdown2.markdown(source, extras=['tables','header-ids','fenced-code-blocks'])
# Keep editable Mermaid in the Markdown; embed a portable vector in the HTML.
architecture = (out/'system-architecture.svg').read_text()
body, replacements = re.subn(r'<pre><code>flowchart TB.*?</code></pre>', architecture, body, count=1, flags=re.S)
assert replacements == 1, 'Missing architecture diagram placeholder'
atlas = root/'android/app/src/main/res/drawable-nodpi/weasel_poses.png'
art = 'data:image/png;base64,'+base64.b64encode(atlas.read_bytes()).decode()
nav='<nav><span>Today</span><span>Week</span><span>Food</span></nav>'
def phone(name, content, tab=True):
    return f'<figure><figcaption>{name}</figcaption><div class="phone"><div class="status">9:41 <span>● ▰</span></div><div class="screen">{content}</div>{nav if tab else ""}</div></figure>'
def row(icon,title,detail='',state='✎'):
    return f'<div class="row"><i>{icon}</i><div><b>{title}</b><small>{detail}</small></div><span class="action">{state}</span></div>'
def actions(a='Log',b='Skip'):
    return f'<div class="actions"><span class="primary">{a}</span><span>{b}</span></div>'
def close(title):return f'<div class="detailhead"><h3>{title}</h3><span>×</span></div>'
curve='<svg viewBox="0 0 280 110" role="img" aria-label="Illustrative heart rate curve with a missing interval"><path d="M0 25H280 M0 60H280 M0 95H280" stroke="#d9e0e9" fill="none"/><path d="M0 95L12 83 23 91 34 60 45 70 56 29 65 21 74 49 83 81 94 63 105 43 116 68 M137 73L149 41 160 20 172 37 183 72 194 55 205 18 216 30 227 72 238 48 250 64 262 79 280 86" fill="none" stroke="#2465da" stroke-width="3"/></svg>'
weight='<svg viewBox="0 0 280 115" role="img" aria-label="Illustrative observed weight points"><path d="M10 25H270 M10 60H270 M10 95H270" stroke="#d9e0e9"/><path d="M20 35L95 55 170 48 250 72" stroke="#2465da" fill="none" stroke-width="2"/><g fill="#2465da"><circle cx="20" cy="35" r="5"/><circle cx="95" cy="55" r="5"/><circle cx="170" cy="48" r="5"/><circle cx="250" cy="72" r="5"/></g></svg>'
bar='<div class="thin">820 / 2,000 kcal<br><small>54 / 140g P · 90 / 220g C · 27 / 60g F</small></div>'
phones=[]
phones.append(phone('01 · Today',f'<div class="hero"><h2>91 days<br>to Open</h2><div class="mascot" aria-label="Example weasel mascot"></div><span class="gear">⚙</span></div>'+bar+'<section class="soft"><h3>Today</h3>'+row('◌','Breakfast','Eggs, toast and fruit')+row('◇','Stretch','Five-minute routine')+'</section><section class="soft"><h3>Next meal</h3>'+row('◌','Lunch · 12:30 PM','100g chicken · 180g cooked rice · 150g broccoli · 12–20 oz water')+'</section><h3>Later today</h3>'+row('◈','BJJ · Moderate','6:00 PM')+row('◇','Recovery','8:00 PM')+'<p class="quiet">Walks · 32 min</p>'))
phones.append(phone('02 · Week','<div class="detailhead"><span>‹</span><h3>Jun 8–14</h3><span>›</span></div><div class="day"><strong>8 <span>Monday</span></strong><small>Recovery</small></div><div class="day"><strong>9 <span>Tuesday</span></strong><small>BJJ · Intense</small></div><div class="day"><strong>10 <span>Wednesday</span></strong><small>Rest · Recovery</small></div>'+row('◇','Breathing','8:00 AM · 5 min','✓')+row('◇','Water','8:05 AM · 12–20 oz')+'<div class="day"><strong>11 <span>Thursday</span></strong><small>Weights · BJJ</small></div><div class="day"><strong>12 <span>Friday</span></strong><small>Recovery</small></div><div class="day"><strong>13 <span>Saturday</span></strong><small>BJJ · Moderate</small></div><div class="day"><strong>14 <span>Sunday</span></strong><small>Weight · Weights</small></div><div class="outline">Weekly wrap-up</div>'))
phones.append(phone('03 · Food','<div class="detailhead"><span>‹</span><h3>Wednesday, Jun 10</h3><span>›</span></div><div class="nutrition"><span class="action right">✎</span><h2>820 <small>/ 2,000 kcal</small></h2><div class="meter"><span style="width:41%"></span></div><div class="macros"><span><b>54g</b><small>of 140g protein</small></span><span><b>90g</b><small>of 220g carbs</small></span><span><b>27g</b><small>of 60g fat</small></span></div></div>'+row('◌','Eggs, toast and fruit','Breakfast · 380 kcal','')+row('◌','Chicken and rice','Lunch · 440 kcal','')+'<h3>Keep eating <span class="right" aria-label="Restore dismissed meals">↶</span></h3><p class="quiet">Breakfast dismissed <span class="right">Undo</span></p>'+row('◌','Dinner','7:00 PM · Fish, potatoes, vegetables','')+row('◌','Recovery snack','9:00 PM · Yogurt and berries','')))
phones.append(phone('04 · Food entry','<div class="detailhead"><span>×</span><span class="add">Add</span></div><div class="input">Two eggs, 80g toast and a banana</div><div class="quiet">Details ⌄</div>',False))
phones.append(phone('05 · Food review',close('')+'<section class="soft"><h3>Two eggs, 80g toast and a banana</h3><p>320g</p><h2>455 kcal</h2><p>21g protein · 65g carbs · 13g fat</p><span class="action right">✎</span></section><div class="save">✓</div>',False))
zones=''.join(f'<div class="zone"><small>Zone {i}</small><small>{t} min</small><div class="meter"><span style="width:{w}%"></span></div></div>' for i,t,w in [(1,18,20),(2,24,27),(3,22,25),(4,20,23),(5,2,3)])
phones.append(phone('06 · BJJ detail',close('BJJ')+'<small>Tuesday · 6:00 PM <span class="add">Move</span></small>'+actions()+'<section class="soft"><h2>90 min</h2><p>134 bpm avg · 176 peak</p>'+curve+'</section>'+zones+'<small>86 min covered · 4 min without HR</small><p class="add">Choose workout</p>',False))
phones.append(phone('07 · Strength',close('Weights')+'<small>Thursday · 4:00 PM <span class="add">Move</span></small>'+actions('Done','Skipped')+'<h3>Session plan</h3>'+row('▣','Hip thrust','3 × 8 · 16 kg','')+row('▣','Hollow hold','3 × 20 sec','')+row('▣','Dead bug','3 × 8 per side',''),False))
phones.append(phone('08 · Recovery',close('Recovery')+'<small>Tuesday · 8:00 PM <span class="add">Move</span></small>'+row('◇','Breathing','5 min','✓')+row('◇','Water','12–20 oz')+row('◇','Tissue work','Your prescribed routine')+row('◇','Legs up','8–10 min')+'<section class="soft"><h3>Water</h3><p>12–20 oz of water</p>'+actions()+'</section>',False))
phones.append(phone('09 · Weekly wrap-up',close('Weekly wrap-up')+'<small>Jun 8–14</small>'+weight+'<h3>This week</h3><p>Your logged training included two mat sessions and a strength session. Recovery steps were completed after Tuesday’s session.</p><h3>Considerations</h3><p>Keep the post-session routine easy to start after the late class.</p><small class="footnote">Based on logged days. Food recorded on 4 of 7 days; one weekly weight observation.</small>',False))
phones.append(phone('10 · Settings',close('Settings')+row('↻','Sync','Connected · Updated recently','›')+row('♡','Trackers','Sources and refresh','›')+row('◷','Notifications','Categories and quiet hours','›')+row('○','Weight goal','Your selected goal','›')+row('◌','Nutrition targets','Daily targets','›')+row('▤','Data','Export and restore','›'),False))
phones.append(phone('11 · Weight',close('Weight')+'<small>Sunday, Jun 14 · After waking</small><div class="input" style="min-height:70px;margin-top:20px">173.8 lb</div><p class="add">Choose tracker reading</p><div class="save">✓</div>'+weight+'<small>May 24 · May 31 · Jun 7 · Jun 14</small>',False))
phones.append(phone('12 · Reminder',close('Reminder')+'<section class="soft"><h3>BJJ · Moderate</h3><p>Class is at 6:00 PM. I would offer to carry your bag, but we both know how that would end.</p><div class="outline">Open session</div></section><h3>Snooze</h3><div class="actions"><span>10 min</span><span>30 min</span></div><div class="outline">60 min · Choose time: 7:00 PM</div><p class="quiet">Dismiss</p>',False))
visuals='<section id="reference-layouts"><div class="eyebrow">Visual reference</div><h2>Screen designs</h2><p>Fresh schematic layouts reflecting the reviewed interaction rules. All dates, food totals and prescriptions below are fictional fixtures. The animal is an example; choose your own. These are design references, not screenshots or a working prototype.</p><div class="phones">'+''.join(phones)+'</div></section>'
css='''
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f5f7fa;color:#10151e;font:16px/1.65 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}main{max-width:1100px;margin:auto;padding:64px 42px;background:white}h1{font-size:48px;line-height:1.08;letter-spacing:-1.8px;margin:0 0 14px}h2{font-size:29px;line-height:1.25;margin:50px 0 18px;letter-spacing:-.5px}h3{font-size:20px;line-height:1.3;margin:28px 0 12px}p{margin:12px 0 20px}a{color:#2465da}strong{font-weight:650}li{margin:8px 0}table{width:100%;border-collapse:collapse;font-size:14px;margin:24px 0}th,td{padding:12px 14px;border-bottom:1px solid #d9e0e9;text-align:left;vertical-align:top}th{background:#edf3ff}td:first-child{width:25%;font-weight:550}blockquote{margin:26px 0;padding:12px 24px;background:#edf3ff;border-left:4px solid #2465da}code{font-size:.9em}header{padding:0 0 25px;border-bottom:1px solid #d9e0e9}.eyebrow{color:#2465da;font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:2px}.links{display:flex;flex-wrap:wrap;gap:12px;margin:25px 0}.links a{padding:8px 14px;background:#edf3ff;text-decoration:none;border-radius:8px;font-size:13px}.phones{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:26px 18px;margin-top:30px}figure{margin:0;min-width:0}figcaption{font-size:12px;font-weight:700;margin:0 0 9px;color:#535f70}.phone{border:1px solid #d9e0e9;border-radius:25px;background:white;min-height:620px;overflow:hidden;display:flex;flex-direction:column;box-shadow:0 8px 20px #10151e08;font-size:12px;line-height:1.5}.status{padding:13px 20px 0;font-size:10px;font-weight:700;display:flex;justify-content:space-between}.screen{padding:19px 16px;flex:1}.phone h2{font-size:23px;line-height:1.2;margin:6px 0 12px;letter-spacing:-.5px}.phone h3{font-size:14px;margin:15px 0 10px}.phone p{margin:9px 0 15px}.phone small{display:block;font-size:10px;color:#535f70}.hero{position:relative;display:flex;align-items:center;min-height:105px}.hero h2{flex:1}.mascot{width:85px;height:95px;background-image:url(ART);background-size:300% 200%;background-position:0 0}.gear{position:absolute;top:-4px;right:0;color:#535f70}.thin{font-weight:600;padding:10px 0 15px}.soft{background:#edf3ff;border-radius:9px;padding:12px;margin:12px 0}.soft h3:first-child{margin-top:0}.row{display:flex;gap:10px;align-items:center;padding:12px 0;border-bottom:1px solid #d9e0e9}.row>div{flex:1;min-width:0}.row i{font-style:normal;font-size:15px;background:#edf3ff;color:#2465da;border-radius:7px;min-width:26px;text-align:center;padding:4px}.row b{font-size:12px;font-weight:600}.action{color:#2465da;font-size:17px;min-width:18px}.right{float:right}.phone nav{display:flex;justify-content:space-around;padding:15px 8px;border-top:1px solid #d9e0e9;color:#2465da;font-size:11px}.detailhead{display:flex;justify-content:space-between;align-items:center;gap:8px;margin-bottom:18px}.detailhead h3{margin:0;font-size:18px}.detailhead>span{font-size:19px}.day{border-bottom:1px solid #d9e0e9;padding:10px 0}.day strong{font-size:15px}.day strong span{font-size:12px;margin-left:12px}.day small{margin-left:27px}.outline{border:1px solid #d9e0e9;border-radius:7px;padding:10px;text-align:center;color:#2465da;margin-top:17px}.nutrition{padding:6px 0 16px}.nutrition h2 small{display:inline;font-size:11px;font-weight:400}.macros{display:flex;justify-content:space-between;gap:5px;margin-top:14px}.macros b{font-size:16px}.macros small{font-size:9px}.meter{height:5px;background:#e4eaf2;border-radius:5px;overflow:hidden}.meter span{display:block;height:100%;background:#2465da}.add{color:#2465da;font-weight:600}.input{min-height:150px;padding:16px;border:1px solid #d9e0e9;border-radius:9px;font-size:15px}.quiet{color:#535f70;padding:14px 0}.save{margin:20px 0 0 auto;background:#2465da;color:white;border-radius:50%;width:40px;height:40px;text-align:center;line-height:40px;font-size:23px}.actions{display:flex;justify-content:center;gap:12px;margin:19px 0}.actions span{border:1px solid #d9e0e9;border-radius:8px;padding:8px 25px;color:#2465da;font-size:12px}.actions .primary{background:#2465da;color:white;border-color:#2465da}.zone{display:flex;flex-wrap:wrap;justify-content:space-between;margin:10px 0}.zone .meter{width:100%;margin-top:4px;height:4px}.footnote{border-top:1px solid #d9e0e9;padding-top:12px;margin-top:25px}svg{width:100%;height:auto}.phone section{scroll-margin-top:15px}#reference-layouts{padding-bottom:45px;border-bottom:1px solid #d9e0e9;margin-bottom:45px}footer{margin-top:60px;padding-top:20px;border-top:1px solid #d9e0e9;font-size:12px;color:#535f70}@media(max-width:900px){.phones{grid-template-columns:repeat(2,minmax(0,1fr))}main{padding:35px 24px}}@media(max-width:560px){.phones{grid-template-columns:minmax(0,340px);justify-content:center}main{padding:28px 16px}h1{font-size:36px}h2{font-size:25px}table{font-size:12px}th,td{padding:8px}.phone{min-height:620px}}@media print{body,main{background:white}main{max-width:none;padding:0}.links{display:none}h2,h3{break-after:avoid}figure,blockquote,tr{break-inside:avoid}.phones{grid-template-columns:repeat(2,minmax(0,1fr))}.phone{box-shadow:none}a{color:inherit;text-decoration:none}p,li{orphans:3;widows:3}h1{font-size:36px}}'''.replace('ART',art)
# Insert the visual reference after the introductory paragraphs, before section 1.
marker='<h2 id="1-what-you-are-building">'
assert marker in body
body=body.replace(marker,visuals+marker,1)
links='<div class="links"><a href="#reference-layouts">Designs</a><a href="#2-personalize-before-building">Personalize</a><a href="#6-architecture-without-a-prescribed-stack">Architecture</a><a href="#11-build-recipe-for-your-ai">AI recipe</a><a href="#12-acceptance-tests-and-handoff">Acceptance tests</a></div>'
page=f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Personal Training App — Shareable Blueprint</title><style>{css}</style></head><body><main><header><div class="eyebrow">Shareable product blueprint · technology agnostic</div>{links}</header>{body}<footer>Self-contained document. No scripts, analytics, remote fonts, credentials or real personal records. Reference art embedded for illustration; choose a character for your own app.</footer></main></body></html>'
(out/'PERSONAL_TRAINING_APP_BLUEPRINT.html').write_text(page)
print('Wrote HTML:',len(page),'bytes')
